reset role;
begin;
insert into auth.users(id) values
 ('a6000000-0000-4000-8000-000000000001'),
 ('a6000000-0000-4000-8000-000000000002'),
 ('a6000000-0000-4000-8000-000000000003'),
 ('a6000000-0000-4000-8000-000000000004');
set local role authenticated;
do $$
declare
  host uuid:='a6000000-0000-4000-8000-000000000001';
  maker uuid:='a6000000-0000-4000-8000-000000000002';
  kai uuid:='a6000000-0000-4000-8000-000000000003';
  stranger uuid:='a6000000-0000-4000-8000-000000000004';
  run uuid:=gen_random_uuid(); run2 uuid:=gen_random_uuid();
  state jsonb; result jsonb; retry jsonb; published jsonb; release jsonb;
  invite_m text; invite_k text; req uuid; source uuid; tip uuid; source_member uuid;
  payload jsonb:='{"title":"Names We Keep","panels":[{"asset":"source-writing","caption":"An entry for every person who leaves something to repair."},{"asset":"source-ledger","caption":"Nika keeps a paper ledger when the city forgets."}]}';
begin
  perform set_config('request.jwt.claim.sub',host::text,true);
  state:=public.world_demo_create(run,'concept-2026-10-04');
  if jsonb_array_length(state->'works')<>1 or jsonb_array_length(state->'invitations')<>2 then raise exception 'Missing opening or invitations'; end if;
  if public.world_demo_create(run,'concept-2026-10-04')<>state then raise exception 'Create retry changed run'; end if;
  select e->>'token' into invite_m from jsonb_array_elements(state->'invitations') e where e->>'role'='maker';
  select e->>'token' into invite_k from jsonb_array_elements(state->'invitations') e where e->>'role'='continuing';
  if length(invite_m)<>64 or invite_m=invite_k then raise exception 'Weak or duplicate invitation'; end if;
  begin perform public.world_demo_join(run,invite_m,'concept-2026-10-04'); raise exception 'Host claimed maker'; exception when raise_exception then if sqlerrm not like 'This account already%' then raise; end if; end;
  perform public.world_demo_create(run2,'concept-2026-10-04');
  perform set_config('request.jwt.claim.sub',stranger::text,true);
  begin perform public.world_demo_read(run); raise exception 'Stranger read private run'; exception when raise_exception then if sqlerrm not like 'This rehearsal is private%' then raise; end if; end;
  begin perform public.world_demo_join(run,'invalid','concept-2026-10-04'); raise exception 'Invalid invite worked'; exception when raise_exception then if sqlerrm not like 'This invitation is unavailable%' then raise; end if; end;
  perform set_config('request.jwt.claim.sub',maker::text,true);
  begin perform public.world_demo_join(run,invite_m,'wrong-terms'); raise exception 'Wrong terms worked'; exception when raise_exception then if sqlerrm not like 'Read and accept%' then raise; end if; end;
  state:=public.world_demo_join(run,invite_m,'concept-2026-10-04');
  source_member:=(state#>>'{me,id}')::uuid;
  if state->'invitations'<>'[]' or state->>'draft' is not null then raise exception 'Member received secrets'; end if;
  if public.world_demo_join(run,invite_m,'concept-2026-10-04')<>state then raise exception 'Join replay failed'; end if;
  begin perform public.world_demo_command(run,gen_random_uuid(),(state->>'revision')::int,'select','{}'); raise exception 'Maker selected'; exception when raise_exception then if sqlerrm not like 'Only the rehearsal curator%' then raise; end if; end;
  begin perform public.world_demo_command(run,gen_random_uuid(),(state->>'revision')::int,'save_draft','{"title":"Forged","panels":[{"asset":"outcome","caption":"Stolen outcome"}]}'); raise exception 'Maker used wrong asset'; exception when raise_exception then if sqlerrm not like 'Choose artwork prepared%' then raise; end if; end;
  req:=gen_random_uuid();
  result:=public.world_demo_command(run,req,(state->>'revision')::int,'save_draft',payload);
  retry:=public.world_demo_command(run,req,(state->>'revision')::int,'save_draft',payload);
  if not (retry->>'replayed')::boolean or result->'state'<>retry->'state' then raise exception 'Save retry duplicated'; end if;
  begin perform public.world_demo_command(run,req,(state->>'revision')::int,'save_draft',payload||'{"title":"Changed"}'); raise exception 'Changed replay accepted'; exception when raise_exception then if sqlerrm not like 'This request was already used%' then raise; end if; end;
  begin perform public.world_demo_command(run,gen_random_uuid(),(state->>'revision')::int,'publish_work','{}'); raise exception 'Stale publish accepted'; exception when raise_exception then if sqlerrm not like 'The rehearsal changed%' then raise; end if; end;
  state:=result->'state';
  if state#>>'{draft,title}'<>'Names We Keep' then raise exception 'Draft lost'; end if;
  perform set_config('request.jwt.claim.sub',host::text,true);
  if public.world_demo_read(run)->>'draft' is not null then raise exception 'Curator saw private draft'; end if;
  perform set_config('request.jwt.claim.sub',kai::text,true);
  begin perform public.world_demo_join(run,invite_m,'concept-2026-10-04'); raise exception 'Kai stole seat'; exception when raise_exception then if sqlerrm not like 'This seat has already been claimed%' then raise; end if; end;
  state:=public.world_demo_join(run,invite_k,'concept-2026-10-04');
  begin perform public.world_demo_command(run,gen_random_uuid(),(state->>'revision')::int,'save_draft','{"title":"Too early","panels":[]}'); raise exception 'Continued a private draft'; exception when raise_exception then if sqlerrm not like 'Mira needs to publish%' then raise; end if; end;
  perform set_config('request.jwt.claim.sub',maker::text,true);
  state:=public.world_demo_read(run); req:=gen_random_uuid();
  result:=public.world_demo_command(run,req,(state->>'revision')::int,'publish_work','{}');
  source:=(result->>'resultId')::uuid;
  retry:=public.world_demo_command(run,req,0,'publish_work','{}');
  if not (retry->>'replayed')::boolean or retry->>'resultId'<>source::text then raise exception 'Duplicate publication'; end if;
  state:=result->'state';
  select e into published from jsonb_array_elements(state->'works') e where e->>'id'=source::text;
  if published->>'maker_id'<>source_member::text or published->>'maker_label'<>'Mira' or state->>'draft' is not null then raise exception 'Authorship or private draft cleanup wrong'; end if;
  begin update public.world_demo_works set maker_label='Fake'; raise exception 'Client changed authorship'; exception when insufficient_privilege then null; end;
  begin select * from public.world_demo_drafts; raise exception 'Direct private read'; exception when insufficient_privilege then null; end;
  begin perform public.world_demo_command(run,gen_random_uuid(),(state->>'revision')::int,'save_draft',payload); raise exception 'Mutated published work'; exception when raise_exception then if sqlerrm not like 'Your contribution is already published%' then raise; end if; end;
  perform set_config('request.jwt.claim.sub',host::text,true);
  state:=public.world_demo_read(run2);
  begin perform public.world_demo_command(run2,gen_random_uuid(),(state->>'revision')::int,'select',jsonb_build_object('sourceId',source,'reason','Cross-run')); raise exception 'Cross-run source accepted'; exception when raise_exception then if sqlerrm not like 'Choose a published source%' then raise; end if; end;
  state:=public.world_demo_read(run);
  result:=public.world_demo_command(run,gen_random_uuid(),(state->>'revision')::int,'select',jsonb_build_object('sourceId',source,'reason','The ledger gives the neighborhood a shared memory.'));
  state:=result->'state';
  if state->'releases'<>'[]' then raise exception 'Selection fabricated inclusion'; end if;
  begin perform public.world_demo_command(run,gen_random_uuid(),(state->>'revision')::int,'publish_release',jsonb_build_object('tipId',source)); raise exception 'Released without continuation'; exception when raise_exception then if sqlerrm not like 'Kai needs to publish%' then raise; end if; end;
  state:=(public.world_demo_command(run,gen_random_uuid(),(state->>'revision')::int,'withdraw','{}'))->'state';
  state:=(public.world_demo_command(run,gen_random_uuid(),(state->>'revision')::int,'select',jsonb_build_object('sourceId',source,'reason','The ledger reconnects neighbors.')))->'state';
  if jsonb_array_length(state->'selections')<>2 then raise exception 'Withdrawal erased selection history'; end if;
  perform set_config('request.jwt.claim.sub',kai::text,true);
  state:=public.world_demo_read(run);
  state:=(public.world_demo_command(run,gen_random_uuid(),(state->>'revision')::int,'save_draft','{"title":"A name to call","panels":[{"asset":"outcome","caption":"With the network down, Nika finds the old contact in the paper ledger."}]}'))->'state';
  result:=public.world_demo_command(run,gen_random_uuid(),(state->>'revision')::int,'publish_work','{}');
  tip:=(result->>'resultId')::uuid;
  perform set_config('request.jwt.claim.sub',host::text,true);
  state:=public.world_demo_read(run); req:=gen_random_uuid();
  result:=public.world_demo_command(run,req,(state->>'revision')::int,'publish_release',jsonb_build_object('tipId',tip));
  retry:=public.world_demo_command(run,req,0,'publish_release',jsonb_build_object('tipId',tip));
  if not (retry->>'replayed')::boolean or retry->'state'<>result->'state' then raise exception 'Release replay changed credit'; end if;
  state:=result->'state'; release:=state#>'{releases,0}';
  if jsonb_array_length(release#>'{snapshot,works}')<>3 or release#>>'{snapshot,works,1,maker_label}'<>'Mira' or release#>>'{snapshot,works,2,maker_label}'<>'Kai' or release#>>'{snapshot,curator,label}'<>'Demo curator' then raise exception 'Release lost distinct roles or path'; end if;
  if release->>'digest'<>encode(sha256(convert_to((release->'snapshot')::text,'UTF8')),'hex') then raise exception 'Snapshot digest mismatch'; end if;
  if (release->'snapshot')::text like '%'||host::text||'%' or (release->'snapshot')::text like '%token%' then raise exception 'Release leaked auth or invite'; end if;
  begin update public.world_demo_releases set snapshot='{}'; raise exception 'Release mutable'; exception when insufficient_privilege then null; end;
  begin perform public.world_demo_command(run,gen_random_uuid(),(state->>'revision')::int,'withdraw','{}'); raise exception 'Withdrew published chapter'; exception when raise_exception then if sqlerrm not like 'Chapter 2 is published%' then raise; end if; end;
  perform set_config('request.jwt.claim.sub',maker::text,true);
  if public.world_demo_read(run)#>'{releases,0}'<>release then raise exception 'Returning maker sees another release'; end if;
  perform set_config('request.jwt.claim.sub',stranger::text,true);
  begin perform public.world_demo_command(run,gen_random_uuid(),0,'publish_release','{}'); raise exception 'Stranger published'; exception when raise_exception then if sqlerrm not like 'This rehearsal is private%' then raise; end if; end;
end $$;
set local role anon;
do $$ begin
  begin perform public.world_demo_read(gen_random_uuid()); raise exception 'Unauthenticated RPC'; exception when insufficient_privilege then null; end;
end $$;
reset role;
rollback;
